// Isometric battlefield renderer: gameplay remains on the same logical grid.
 const ISO={x:294,y:35,sx:.6,sy:.3};
 function isoPoint(x,y){return{x:ISO.x+(x/CW-y/CH)*30,y:ISO.y+(x/CW+y/CH)*15}}
 function isoCell(x,y){return isoPoint(x*CW,y*CH)}
