Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -8,9 +8,9 @@
 :root{--bg:#07111a;--panel:#0d1a24;--panel2:#10212c;--line:#243844;--text:#e5f1ef;--muted:#83989c;--mint:#71f0c1;--amber:#ffc878;--red:#ff6e76;--blue:#77cfff;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}
