WAVE'))await new Promise(r=>setTimeout(r,200));return {wave:document.querySelector('#wave').textContent,state:document.querySelector('#waveState').textContent,timeline:document.querySelector('#timeline').textContent,cards:[...document.querySelectorAll('.tower-card')].map(b=>b.dataset.type),zone:document.querySelector('#zoneTitle').textContent,transition:document.querySelector('#overlay').classList.contains('show'),modal:document.querySelector('#modalTitle').textContent,core:document.querySelector('#lives').textContent,credits:document.querySelector('#money').textContent}})()`);console.log(JSON.stringify(result));if(result.transition)break;if(result.state!=='AWAITING DEPLOYMENT')break;}ws.close();
